import { getContentMountState } from '@dreadnought/core';
const opened = getContentMountState({ active: true, mountPolicy: 'lazy' });
const closed = getContentMountState({ active: false, visited: opened.visited, mountPolicy: 'lazy' });

import { getVisibleMenuRows } from '@dreadnought/core';
type Item = { value: string; children?: readonly Item[] };
const items: readonly Item[] = [{ value: 'export', children: [{ value: 'pdf' }] }];
const rows = getVisibleMenuRows(items, { getKey: item => item.value, getChildren: item => item.children, getKind: item => item.children ? 'submenu' : 'item', expandedKeys: ['export'] });

import { getTreeCheckState } from '@dreadnought/core';
type Node = { id: string; children?: readonly Node[] };
const records: readonly Node[] = [{ id: 'root', children: [{ id: 'a' }, { id: 'b' }] }];
const state = getTreeCheckState(records, { getKey: node => node.id, getChildren: node => node.children, checkedKeys: ['a'], action: { key: 'b', checked: true } });

import { getHistoryState } from '@dreadnought/core';
const initial = { past: [], present: 'hello', future: [] };
const edited = getHistoryState(initial, { type: 'commit', value: 'world' });
const undone = getHistoryState(edited, { type: 'undo' });

import { getNavigationDirection, getSteppedValue } from '@dreadnought/core';
const grid = { min: 1, max: 6, step: 2 };
const value = getSteppedValue(4, grid);
const direction = getNavigationDirection('ArrowRight', { orientation: 'horizontal' });
const candidate = direction === 'first' ? grid.min : direction === 'last' ? grid.max : value + (direction === 'next' ? grid.step : direction === 'previous' ? -grid.step : 0);
const next = getSteppedValue(candidate, grid);
const end = getSteppedValue(grid.max, grid);

import { getSteppedRange } from '@dreadnought/core';
const grid = { min: 0, max: 100, step: 5 };
const range = getSteppedRange([82, 18], grid);
const next = getSteppedRange(range, grid, { index: 0, value: 90 });

import { getComboboxKeyAction, getNextEnabledValue, getDisclosureOpen, getSelectionValue } from '@dreadnought/core';
const items = [{ value: 'first' }, { value: 'last' }];
const action = getComboboxKeyAction('ArrowDown', { open: true });
const next = action?.type === 'navigate' ? getNextEnabledValue(items, 'first', action.direction, { loop: false }) : undefined;
const closed = getComboboxKeyAction('Tab', { open: true });
const open = closed?.type === 'close' ? getDisclosureOpen(true, 'close') : true;
const select = getComboboxKeyAction('Enter', { open: true });
const value = select?.type === 'select' && next !== undefined ? getSelectionValue<string>(null, { type: 'select', value: next }) : null;
// action.preventDefault — решение; реальное событие и фокус остаются адаптеру.

import { getDisclosureState } from '@dreadnought/core';
const state = getDisclosureState({ open: true, triggerId: 'settings-trigger', panelId: 'settings-panel' });
// Примените state.triggerProps и state.panelProps в своём фреймворке.

import { getDisclosureOpen, getDisclosureState } from '@dreadnought/core';
const next = getDisclosureOpen(false, 'toggle');
const state = getDisclosureState({ open: next, triggerId: 'details-trigger', panelId: 'details-panel' });
const blocked = getDisclosureOpen(true, 'close', { disabled: true }); // true

import { getNavigationDirection, getNextEnabledValue } from '@dreadnought/core';
const items = [{ value: 'copy' }, { value: 'save' }];
const direction = getNavigationDirection('ArrowRight', { orientation: 'horizontal' });
const next = direction === undefined ? undefined : getNextEnabledValue(items, 'copy', direction);
const cursorKey = getNavigationDirection('Home', { homeEnd: false });
// Следующий ключ — save; курсорная клавиша — undefined. События и фокус остаются в адаптере.

import { getTypeaheadValue } from '@dreadnought/core';
const items = [{ value: 'news', text: 'Новости' }, { value: 'settings', text: 'Настройки' }];
const next = getTypeaheadValue(items, 'news', 'на');
const refined = getTypeaheadValue(items, 'settings', 'наст', { includeCurrent: true });
// Результат — ключ. Хранение запроса и перенос фокуса остаются в вашем компоненте.

import { getSelectionValue } from '@dreadnought/core';
const single = getSelectionValue<string>(null, { type: 'select', value: 'news' });
const multiple = getSelectionValue(['news'], { type: 'toggle', value: 'updates' }, { required: true, disabledValues: ['archive'] });

import { getNextEnabledValue, getSelectionValue } from '@dreadnought/core';
const items = [{ value: 'news' }, { value: 'archive', disabled: true }, { value: 'updates' }];
const focused = getNextEnabledValue(items, 'news', 'next', { loop: false });
const selected = focused === undefined ? null : getSelectionValue<string>(null, { type: 'select', value: focused });
// Связывайте фокус и выбор только если это нужно вашему компоненту.

import { getNextEnabledValue } from '@dreadnought/core';
const items = [{ value: 'first' }, { value: 'disabled', disabled: true }, { value: 'last' }];
const next = getNextEnabledValue(items, 'first', 'next', { loop: false });
const first = getNextEnabledValue(items, 'last', 'first');
// Результат — ключ; actual focus и обработчик клавиатуры остаются в вашем коде.

import { getVisibleTreeRows, getTreeKeyAction } from '@dreadnought/core';
type Node = { id: number; children?: readonly Node[] };
const records: readonly Node[] = [{ id: 0, children: [{ id: 1 }] }];
const rows = getVisibleTreeRows(records, { getKey: node => node.id, getChildren: node => node.children });
const action = getTreeKeyAction(rows, 0, 'ArrowRight');

import { getVisibleTreeRows, getSelectionValue } from '@dreadnought/core';
type Folder = { id: string; nodes?: readonly Folder[] };
const folders: readonly Folder[] = [{ id: 'docs', nodes: [{ id: 'file' }] }];
const expanded = getSelectionValue<string>([], { type: 'toggle', value: 'docs' });
const rows = getVisibleTreeRows(folders, { getKey: folder => folder.id, getChildren: folder => folder.nodes, expandedKeys: expanded });
